def write_imp(fn, nspl, off, decoy_lines):
    s=[';redcode-94',';name ImpD',';assert CORESIZE == 8000','start   spl 1']
    for i in range(nspl-1):
        s.append('        spl 1')
    s.append(f'imp     mov 0, {off}')
    for dl in decoy_lines:
        s.append(dl)
    s.append('        end start')
    open(fn,'w').write('\n'.join(s)+'\n')

